    private function mapUserRoleAssignament(ServerRequestInterface $request, UserRoleAssignamentRetrieveResult $value): UserRoleAssignamentApiDTO
    {
        $this->logDebug("Map entity to output dto for User role assignament");
        $span = $this->startSpan("Map entity to output dto for User role assignament");
        try {
            $user = $value->getUser();
            $relyingParty = $value->getRelyingParty();
            $trustedClient = $value->getTrustedClient();
            $dto = new UserRoleAssignamentApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->relyingParty = $relyingParty ? ['$ref' => $relyingParty->uid()] : null;
            $dto->trustedClient = $trustedClient ? ['$ref' => $trustedClient->uid()] : null;
            $roles = [];
            $existentsRoles = $value->getRoles();
            if (null !== $existentsRoles) {
                foreach ($roles as $item) {
                    $roles[] = [
                    'uid' => $item->uid(),
                    'role' => $item->getRole() ? ['$ref' => $item->getRole()->uid() ] : null,
                    'version' => $item->getVersion(),
                    ];
                }
            }
            $dto->roles = $roles;
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
